-- Errata reading for N14: Same-day visit included (0-7 days after discharge).
WITH r AS MATERIALIZED (SELECT patient, stream, payload FROM records WHERE stream IN ('encounters','adt')), e AS (SELECT json_extract(payload,'$.encounter_id') eid, patient, min(json_extract(payload,'$.event_date')) d, max(json_extract(payload,'$.type')) t FROM r WHERE stream='encounters' GROUP BY 1,2), dc AS (SELECT a.patient, json_extract(a.payload,'$.record_id') rid, json_extract(a.payload,'$.event_date') dd FROM r a JOIN e ON e.eid=json_extract(a.payload,'$.encounter_id') WHERE a.stream='adt' AND json_extract(a.payload,'$.event')='discharge' AND e.t IN ('inpatient','observation') AND json_extract(a.payload,'$.event_date') BETWEEN '2028-08-16' AND '2029-08-08'), f AS (SELECT DISTINCT dc.rid FROM dc JOIN e ON e.patient=dc.patient AND e.t IN ('primary_care','office','pediatric_office','specialty_followup','specialist_office','wellness') AND julianday(e.d)-julianday(dc.dd) BETWEEN 0 AND 7) SELECT round(100.0*(SELECT count(*) FROM f)/(SELECT count(*) FROM dc),1) AS value;
